from collections import deque


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}  # name -> vip bool
        self._tickets = {}    # id -> dict with customer, title, priority, status, seq
        self._next_id = 1
        self._seq = 0
        # Four queues (VIP vs non-VIP) x (priority order), but we can use a
        # single ordered structure. We'll keep separate deques keyed by
        # (is_vip, priority_rank) for O(1) dequeue, plus track order by seq
        # implicitly via insertion into deques.
        self._queues = {
            (True, "critical"): deque(),
            (True, "high"): deque(),
            (True, "normal"): deque(),
            (False, "critical"): deque(),
            (False, "high"): deque(),
            (False, "normal"): deque(),
        }
        self._priority_order = ("critical", "high", "normal")

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if customer not in self._customers:
            raise ValueError(f"Unknown customer: {customer}")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Invalid priority: {priority}")

        ticket_id = self._next_id
        self._next_id += 1
        self._seq += 1
        vip = self._customers[customer]
        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "status": "open",
            "vip": vip,
            "seq": self._seq,
        }
        self._queues[(vip, priority)].append(ticket_id)
        return ticket_id

    def next_ticket(self) -> int | None:
        for vip in (True, False):
            for priority in self._priority_order:
                q = self._queues[(vip, priority)]
                while q:
                    ticket_id = q.popleft()
                    ticket = self._tickets.get(ticket_id)
                    if ticket is not None and ticket["status"] == "open":
                        ticket["status"] = "in_progress"
                        return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise KeyError(f"Unknown ticket: {ticket_id}")
        self._tickets[ticket_id]["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise KeyError(f"Unknown ticket: {ticket_id}")
        ticket = self._tickets[ticket_id]
        if ticket["status"] == "closed":
            raise ValueError(f"Cannot reopen closed ticket: {ticket_id}")
        if ticket["status"] == "open":
            return  # already in queue
        # status is "in_progress": put back into queue
        ticket["status"] = "open"
        self._queues[(ticket["vip"], ticket["priority"])].append(ticket_id)
